        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by calling `napi_schedule()` without disabling bottom halves (BH), which led to warnings about local softirq pending. This situation can occur when the system is processing interrupts and scheduling NAPI concurrently, potentially causing race conditions or improper handling of softirqs.

        Commit message:
        mlx4: do not call napi_schedule() without care

Disable BH around the call to napi_schedule() to avoid following warning

[   52.095499] NOHZ: local_softirq_pending 08
[   52.421291] NOHZ: local_softirq_pending 08
[   52.608313] NOHZ: local_softirq_pending 08

Fixes: 8d59de8f7bb3 ("net/mlx4_en: Process all completions in RX rings after port goes up")
Signed-off-by: Eric Dumazet <edumazet@google.com>
Cc: Erez Shitrit <erezsh@mellanox.com>
Cc: Eugenia Emantayev <eugenia@mellanox.com>
Cc: Tariq Toukan <tariqt@mellanox.com>
Acked-by: Tariq Toukan <tariqt@mellanox.com>
Signed-off-by: David S. Miller <davem@davemloft.net>  

        Patch:

 int mlx4_en_start_port(struct net_device *dev)
 {
 	struct mlx4_en_priv *priv = netdev_priv(dev);
 	struct mlx4_en_dev *mdev = priv->mdev;
 	struct mlx4_en_cq *cq;
 	struct mlx4_en_tx_ring *tx_ring;
 	int rx_index = 0;
 	int err = 0;
 	int i, t;
 	int j;
 	u8 mc_list[16] = {0};

 	if (priv->port_up) {
 		en_dbg(DRV, priv, "start port called while port already up\n");
 		return 0;
 	}

 	INIT_LIST_HEAD(&priv->mc_list);
 	INIT_LIST_HEAD(&priv->curr_list);
 	INIT_LIST_HEAD(&priv->ethtool_list);
 	memset(&priv->ethtool_rules[0], 0,
 	       sizeof(struct ethtool_flow_id) * MAX_NUM_OF_FS_RULES);

 	/* Calculate Rx buf size */
 	dev->mtu = min(dev->mtu, priv->max_mtu);
 	mlx4_en_calc_rx_buf(dev);
 	en_dbg(DRV, priv, "Rx buf size:%d\n", priv->rx_skb_size);

 	/* Configure rx cq's and rings */
 	err = mlx4_en_activate_rx_rings(priv);
 	if (err) {
 		en_err(priv, "Failed to activate RX rings\n");
 		return err;
 	}
 	for (i = 0; i < priv->rx_ring_num; i++) {
 		cq = priv->rx_cq[i];

 		err = mlx4_en_init_affinity_hint(priv, i);
 		if (err) {
 			en_err(priv, "Failed preparing IRQ affinity hint\n");
 			goto cq_err;
 		}

 		err = mlx4_en_activate_cq(priv, cq, i);
 		if (err) {
 			en_err(priv, "Failed activating Rx CQ\n");
 			mlx4_en_free_affinity_hint(priv, i);
 			goto cq_err;
 		}

 		for (j = 0; j < cq->size; j++) {
 			struct mlx4_cqe *cqe = NULL;

 			cqe = mlx4_en_get_cqe(cq->buf, j, priv->cqe_size) +
 			      priv->cqe_factor;
 			cqe->owner_sr_opcode = MLX4_CQE_OWNER_MASK;
 		}

 		err = mlx4_en_set_cq_moder(priv, cq);
 		if (err) {
 			en_err(priv, "Failed setting cq moderation parameters\n");
 			mlx4_en_deactivate_cq(priv, cq);
 			mlx4_en_free_affinity_hint(priv, i);
 			goto cq_err;
 		}
 		mlx4_en_arm_cq(priv, cq);
 		priv->rx_ring[i]->cqn = cq->mcq.cqn;
 		++rx_index;
 	}

 	/* Set qp number */
 	en_dbg(DRV, priv, "Getting qp number for port %d\n", priv->port);
 	err = mlx4_en_get_qp(priv);
 	if (err) {
 		en_err(priv, "Failed getting eth qp\n");
 		goto cq_err;
 	}
 	mdev->mac_removed[priv->port] = 0;

 	priv->counter_index =
 			mlx4_get_default_counter_index(mdev->dev, priv->port);

 	err = mlx4_en_config_rss_steer(priv);
 	if (err) {
 		en_err(priv, "Failed configuring rss steering\n");
 		goto mac_err;
 	}

 	err = mlx4_en_create_drop_qp(priv);
 	if (err)
 		goto rss_err;

 	/* Configure tx cq's and rings */
 	for (t = 0 ; t < MLX4_EN_NUM_TX_TYPES; t++) {
 		u8 num_tx_rings_p_up = t == TX ?
 			priv->num_tx_rings_p_up : priv->tx_ring_num[t];

 		for (i = 0; i < priv->tx_ring_num[t]; i++) {
 			/* Configure cq */
 			cq = priv->tx_cq[t][i];
 			err = mlx4_en_activate_cq(priv, cq, i);
 			if (err) {
 				en_err(priv, "Failed allocating Tx CQ\n");
 				goto tx_err;
 			}
 			err = mlx4_en_set_cq_moder(priv, cq);
 			if (err) {
 				en_err(priv, "Failed setting cq moderation parameters\n");
 				mlx4_en_deactivate_cq(priv, cq);
 				goto tx_err;
 			}
 			en_dbg(DRV, priv,
 			       "Resetting index of collapsed CQ:%d to -1\n", i);
 			cq->buf->wqe_index = cpu_to_be16(0xffff);

 			/* Configure ring */
 			tx_ring = priv->tx_ring[t][i];
 			err = mlx4_en_activate_tx_ring(priv, tx_ring,
 						       cq->mcq.cqn,
 						       i / num_tx_rings_p_up);
 			if (err) {
 				en_err(priv, "Failed allocating Tx ring\n");
 				mlx4_en_deactivate_cq(priv, cq);
 				goto tx_err;
 			}
 			if (t != TX_XDP) {
 				tx_ring->tx_queue = netdev_get_tx_queue(dev, i);
 				tx_ring->recycle_ring = NULL;
 			} else {
 				mlx4_en_init_recycle_ring(priv, i);
 			}

 			/* Arm CQ for TX completions */
 			mlx4_en_arm_cq(priv, cq);

 			/* Set initial ownership of all Tx TXBBs to SW (1) */
 			for (j = 0; j < tx_ring->buf_size; j += STAMP_STRIDE)
 				*((u32 *)(tx_ring->buf + j)) = 0xffffffff;
 		}
 	}

 	/* Configure port */
 	err = mlx4_SET_PORT_general(mdev->dev, priv->port,
 				    priv->rx_skb_size + ETH_FCS_LEN,
 				    priv->prof->tx_pause,
 				    priv->prof->tx_ppp,
 				    priv->prof->rx_pause,
 				    priv->prof->rx_ppp);
 	if (err) {
 		en_err(priv, "Failed setting port general configurations for port %d, with error %d\n",
 		       priv->port, err);
 		goto tx_err;
 	}
 	/* Set default qp number */
 	err = mlx4_SET_PORT_qpn_calc(mdev->dev, priv->port, priv->base_qpn, 0);
 	if (err) {
 		en_err(priv, "Failed setting default qp numbers\n");
 		goto tx_err;
 	}

 	if (mdev->dev->caps.tunnel_offload_mode == MLX4_TUNNEL_OFFLOAD_MODE_VXLAN) {
 		err = mlx4_SET_PORT_VXLAN(mdev->dev, priv->port, VXLAN_STEER_BY_OUTER_MAC, 1);
 		if (err) {
 			en_err(priv, "Failed setting port L2 tunnel configuration, err %d\n",
 			       err);
 			goto tx_err;
 		}
 	}

 	/* Init port */
 	en_dbg(HW, priv, "Initializing port\n");
 	err = mlx4_INIT_PORT(mdev->dev, priv->port);
 	if (err) {
 		en_err(priv, "Failed Initializing port\n");
 		goto tx_err;
 	}

 	/* Set Unicast and VXLAN steering rules */
 	if (mdev->dev->caps.steering_mode != MLX4_STEERING_MODE_A0 &&
 	    mlx4_en_set_rss_steer_rules(priv))
 		mlx4_warn(mdev, "Failed setting steering rules\n");

 	/* Attach rx QP to bradcast address */
 	eth_broadcast_addr(&mc_list[10]);
 	mc_list[5] = priv->port; /* needed for B0 steering support */
 	if (mlx4_multicast_attach(mdev->dev, &priv->rss_map.indir_qp, mc_list,
 				  priv->port, 0, MLX4_PROT_ETH,
 				  &priv->broadcast_id))
 		mlx4_warn(mdev, "Failed Attaching Broadcast\n");

 	/* Must redo promiscuous mode setup. */
 	priv->flags &= ~(MLX4_EN_FLAG_PROMISC | MLX4_EN_FLAG_MC_PROMISC);

 	/* Schedule multicast task to populate multicast list */
 	queue_work(mdev->workqueue, &priv->rx_mode_task);

 	if (priv->mdev->dev->caps.tunnel_offload_mode == MLX4_TUNNEL_OFFLOAD_MODE_VXLAN)
 		udp_tunnel_get_rx_info(dev);

 	priv->port_up = true;

 	/* Process all completions if exist to prevent
 	 * the queues freezing if they are full
 	 */
-	for (i = 0; i < priv->rx_ring_num; i++)
+	for (i = 0; i < priv->rx_ring_num; i++) {
+		local_bh_disable();
 		napi_schedule(&priv->rx_cq[i]->napi);
+		local_bh_enable();
+	}

 	netif_tx_start_all_queues(dev);
 	netif_device_attach(dev);

 	return 0;

 tx_err:
 	if (t == MLX4_EN_NUM_TX_TYPES) {
 		t--;
 		i = priv->tx_ring_num[t];
 	}
 	while (t >= 0) {
 		while (i--) {
 			mlx4_en_deactivate_tx_ring(priv, priv->tx_ring[t][i]);
 			mlx4_en_deactivate_cq(priv, priv->tx_cq[t][i]);
 		}
 		if (!t--)
 			break;
 		i = priv->tx_ring_num[t];
 	}
 	mlx4_en_destroy_drop_qp(priv);
 rss_err:
 	mlx4_en_release_rss_steer(priv);
 mac_err:
 	mlx4_en_put_qp(priv);
 cq_err:
 	while (rx_index--) {
 		mlx4_en_deactivate_cq(priv, priv->rx_cq[rx_index]);
 		mlx4_en_free_affinity_hint(priv, rx_index);
 	}
 	for (i = 0; i < priv->rx_ring_num; i++)
 		mlx4_en_deactivate_rx_ring(priv, priv->rx_ring[i]);

 	return err; /* need to close devices */
 }



